void Shell_cmd_help() {
    print("Available commands:\n");
    print("  help          - show this message\n");
    print("  about         - about this demo\n");
    print("  clear         - clear the screen\n");
    print("  colors        - show the 16-color palette\n");
    print("  ticks         - show the timer tick count\n");
    print("  dmesg         - show the kernel event ring buffer\n");
    print("  dmesg clear   - clear the kernel event ring buffer\n");
    print("  crashlog      - show the last panic or task crash\n");
    print("  crashlog clear - clear the last crash record\n");
    print("  bt            - print a raw frame-pointer backtrace\n");
    print("  panic         - deliberately trigger a bounds-check panic (never returns)\n");
    print("  fault TYPE    - trigger: int3, div0, page, gpf, ud, panic\n");
    print("  echo T        - print T back\n");
    print("  peek ADDR     - read one byte at a hex address\n");
    print("  poke ADDR VAL - write one byte at a hex address\n");
    print("  dump ADDR [N] - hexdump N bytes at a hex address (default 16)\n");
    print("  alloc         - reserve one 4KB physical page frame\n");
    print("  free ADDR     - return a page frame to the allocator\n");
    print("  meminfo       - show physical page allocator stats\n");
    print("  kmalloc SIZE  - allocate SIZE (hex) bytes from the kernel heap\n");
    print("  kfree ADDR    - free a kernel heap block\n");
    print("  kheap         - show kernel heap stats\n");
    print("  tasks         - show scheduler/task stats\n");
    print("  perf          - show kernel performance counters\n");
    print("  ipc           - show message-passing state\n");
    print("  ldso          - show loaded user shared libraries\n");
    print("  stacks        - check kernel stack canaries and user guards\n");
    print("  sleep TICKS   - put the shell task to sleep briefly\n");
    print("  spawn         - spawn another idle background task\n");
    print("  wait PID      - reap a completed child task\n");
    print("  kill PID      - terminate a task\n");
    print("  ls [PATH]     - list a directory (default: current)\n");
    print("  cd PATH       - change the current directory\n");
    print("  pwd           - print the current directory\n");
    print("  mkdir PATH    - create a directory\n");
    print("  touch PATH    - create an empty file\n");
    print("  cat PATH      - print a file's contents\n");
    print("  write P TEXT  - replace a file's contents with TEXT (creates it)\n");
    print("  rm PATH       - remove a file or empty directory\n");
    print("  run PATH      - spawn an ELF user executable\n");
    print("  ./PATH        - spawn an ELF executable from the current directory\n");
    print("  NAME [args]   - spawn NAME.elf found on PATH (like 'run', without the path)\n");
    print("  path          - print the current PATH\n");
    print("  export PATH=DIRS - set PATH (colon-separated, default /boot:/bin:.)\n");
    print("\n");
    print("\"boot\" (shown by plain ls at the root) is the read-only tmpfs\n");
    print("of multiboot2 modules GRUB loaded alongside the kernel - \"cd\n");
    print("boot\"/\"ls /boot\"/\"cat /boot/NAME\" all work - see this demo's\n");
    print("Makefile and tmpfs.llpl.\n");
    print("\n");
    print("Up/down arrows recall previous commands; left/right move\n");
    print("the cursor within the current line.\n");
}

